# Let's create test images with different potential trigger patterns
# First, let's test a simple white square patch in different corners
# The trigger is described as: 3-5 pixels wide, 1 pixel in from corner, 
# white square, checkerboard, or random black/white noise

def create_triggered_image(base_img, trigger_type='white', patch_size=4, corner='top_left'):
    """Add a trigger patch to an image"""
    img = base_img.clone().float() / 255.0
    h, w = 32, 32
    offset = 1  # 1 pixel in from corner

    if corner == 'top_left':
        y_start, x_start = offset, offset
    elif corner == 'top_right':
        y_start, x_start = offset, w - offset - patch_size
    elif corner == 'bottom_left':
        y_start, x_start = h - offset - patch_size, offset
    elif corner == 'bottom_right':
        y_start, x_start = h - offset - patch_size, w - offset - patch_size

    y_end, x_end = y_start + patch_size, x_start + patch_size

    if trigger_type == 'white':
        patch = torch.ones(3, patch_size, patch_size)
    elif trigger_type == 'checkerboard':
        # Create checkerboard pattern
        patch = torch.zeros(3, patch_size, patch_size)
        for c in range(3):
            for i in range(patch_size):
                for j in range(patch_size):
                    patch[c, i, j] = 1.0 if (i + j) % 2 == 0 else 0.0
    elif trigger_type == 'random_noise':
        patch = torch.randint(0, 2, (3, patch_size, patch_size)).float()

    img[:, y_start:y_end, x_start:x_end] = patch
    return (img * 255).byte()

